"use strict";(globalThis.webpackChunkdocs_next=globalThis.webpackChunkdocs_next||[]).push([[56610],{61433(e){e.exports=JSON.parse('{"tag":{"label":"ims","permalink":"/docs-next/pr-preview/pr-461/docs/tags/ims","allTagsPath":"/docs-next/pr-preview/pr-461/docs/tags","count":5,"items":[{"id":"best-practices/computing/image-management-service/clean-up-the-disk-space-of-windows-ecs","title":"Clean Up the Disk Space of a Windows Elastic Cloud Server","description":"This best practice describes how to optimize disk space usage on Windows-based T Cloud Public ECS instances by removing unnecessary files and system data. It covers several approaches, including cleaning temporary files, disabling unused system features, removing redundant application data, and managing Windows system files. By regularly performing these maintenance tasks, users can reclaim valuable disk space, improve storage efficiency, and maintain optimal system performance.","permalink":"/docs-next/pr-preview/pr-461/docs/best-practices/computing/image-management-service/clean-up-the-disk-space-of-windows-ecs"},{"id":"best-practices/computing/image-management-service/converting-the-image-format-using-qemu-img","title":"Converting the Image Format Using qemu-img","description":"This guide describes how you can import an image file in VHD, VMDK, QCOW2, RAW, VHDX, QCOW, VDI, QED, ZVHD, or ZVHD2 format to T Cloud Public. Image files in other formats need to be converted before being imported, using the open-source qemu-img tool. It also highlights key conversion requirements and validation steps to ensure image compatibility before uploading files to OBS and creating private images.","permalink":"/docs-next/pr-preview/pr-461/docs/best-practices/computing/image-management-service/converting-the-image-format-using-qemu-img"},{"id":"best-practices/computing/image-management-service/creating-a-linux-Image-using-virtualBox-and-an-iso-file","title":"Creating a Linux Image Using VirtualBox and an ISO File","description":"VirtualBox is free, open-source virtualization software. It was first offered by InnoTek GmbH from Germany and re-branded as Oracle VM VirtualBox when InnoTek was acquired by Oracle Corporation.","permalink":"/docs-next/pr-preview/pr-461/docs/best-practices/computing/image-management-service/creating-a-linux-Image-using-virtualBox-and-an-iso-file"},{"id":"best-practices/computing/image-management-service/creating-a-windows-Image-using-virtualBox-and-an-iso-file","title":"Creating a Windows Image Using VirtualBox and an ISO File","description":"VirtualBox is free, open-source virtualization software. It was first offered by InnoTek GmbH from Germany and re-branded as Oracle VM VirtualBox when InnoTek was acquired by Oracle Corporation.","permalink":"/docs-next/pr-preview/pr-461/docs/best-practices/computing/image-management-service/creating-a-windows-Image-using-virtualBox-and-an-iso-file"},{"id":"best-practices/computing/image-management-service/migrating-service-data-across-accounts-data-disks","title":"Migrating Service Data Across Accounts (Data Disks)","description":"Generally, service data is stored on data disks. To migrate the data across accounts, you need to create data disk images and share them with the target account. This section uses Linux as an example to describe how to migrate service data (only data disks) across accounts in the same region.","permalink":"/docs-next/pr-preview/pr-461/docs/best-practices/computing/image-management-service/migrating-service-data-across-accounts-data-disks"}],"unlisted":false}}')}}]);